import React from "react";

const MenuItem = ({ itemId, itemPrice, itemName, itemDescription, items }) => {
  return (
    <div className="menu-item" id={`menu-item-${itemId}`}>
      <h1>{items.itemName}</h1>
      <span>${itemPrice}</span>
      <h2>{itemName}</h2>
      <p>{itemDescription}</p>
      <button>Add to Cart</button>
    </div>
  );
};

export default MenuItem;
